package io.invenlio.sales;import jakarta.servlet.http.HttpServletRequest;import java.net.URI;import java.util.Set;import org.slf4j.MDC;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice class SalesExceptionHandler{@ExceptionHandler(SalesException.class)ResponseEntity<ProblemDetail>handle(SalesException e,HttpServletRequest r){HttpStatus s=e.code().endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:Set.of("CONCURRENT_MODIFICATION","CUSTOMER_NUMBER_EXISTS","ALLOCATION_RECONCILIATION_FAILED","SALES_ORDER_ALREADY_SHIPPED","SHIPPED_PROJECTION_MISMATCH").contains(e.code())?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return p(s,e.code(),e.getMessage(),r);}@ExceptionHandler(DataIntegrityViolationException.class)ResponseEntity<ProblemDetail>integrity(DataIntegrityViolationException e,HttpServletRequest r){return p(HttpStatus.CONFLICT,"SALES_CONSTRAINT_VIOLATION","Conflicting sales data",r);}private ResponseEntity<ProblemDetail>p(HttpStatus s,String c,String d,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(s,d);p.setType(URI.create("https://invenlio.io/problems/"+c.toLowerCase().replace('_','-')));p.setTitle(s.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",c);p.setProperty("correlationId",MDC.get("correlationId"));return ResponseEntity.status(s).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
